'use client';
import { useEffect, useState } from 'react';
import { Eye, CheckCircle, XCircle } from 'lucide-react';

export default function OrderPage() {
    const [orders, setOrders] = useState([]);

    useEffect(() => {
        // Demo Orders
        setOrders([
            { id: '#ORD-001', customer: 'Zaid Uddin', items: 3, total: '₹450', status: 'Pending', date: 'Just now' },
            { id: '#ORD-002', customer: 'Rahul Kumar', items: 1, total: '₹120', status: 'Cooking', date: '5 mins ago' },
            { id: '#ORD-003', customer: 'Priya Singh', items: 5, total: '₹1,200', status: 'Delivered', date: '2 hours ago' },
            { id: '#ORD-004', customer: 'Amit Sharma', items: 2, total: '₹340', status: 'Cancelled', date: 'Yesterday' },
        ]);
    }, []);

    const getStatusColor = (status) => {
        switch (status) {
            case 'Pending': return 'bg-yellow-100 text-yellow-600';
            case 'Cooking': return 'bg-blue-100 text-blue-600';
            case 'Delivered': return 'bg-green-100 text-green-600';
            case 'Cancelled': return 'bg-red-100 text-red-600';
            default: return 'bg-gray-100 text-gray-600';
        }
    };

    return (
        <div className="space-y-6">
            <h1 className="text-2xl font-bold text-gray-800">Orders</h1>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <table className="w-full text-left text-gray-600">
                    <thead className="bg-gray-50 text-xs uppercase font-semibold text-gray-500">
                        <tr>
                            <th className="px-6 py-4">Order ID</th>
                            <th className="px-6 py-4">Customer</th>
                            <th className="px-6 py-4">Items</th>
                            <th className="px-6 py-4">Total</th>
                            <th className="px-6 py-4">Date</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {orders.map((order) => (
                            <tr key={order.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4 font-medium text-primary">{order.id}</td>
                                <td className="px-6 py-4">{order.customer}</td>
                                <td className="px-6 py-4">{order.items}</td>
                                <td className="px-6 py-4 font-bold text-gray-800">{order.total}</td>
                                <td className="px-6 py-4 text-sm">{order.date}</td>
                                <td className="px-6 py-4">
                                    <span className={`px-2 py-1 rounded-full text-xs font-semibold ${getStatusColor(order.status)}`}>
                                        {order.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4 flex gap-2">
                                    <button className="p-2 hover:bg-gray-100 rounded-lg text-gray-500" title="View Details"><Eye size={18} /></button>
                                    {order.status === 'Pending' && (
                                        <>
                                            <button className="p-2 hover:bg-green-50 rounded-lg text-green-500" title="Accept"><CheckCircle size={18} /></button>
                                            <button className="p-2 hover:bg-red-50 rounded-lg text-red-500" title="Reject"><XCircle size={18} /></button>
                                        </>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
